from __future__ import annotations

from pathlib import Path
import re


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
WORKFLOW_DIRECTORY = REPOSITORY_ROOT / ".github" / "workflows"
ACTION_USE = re.compile(
    r"(?m)^[ \t]*-[ \t]+uses:[ \t]*(?P<action>actions/(?:checkout|setup-python))@"
    r"(?P<reference>[^ \t#]+)(?P<tail>.*)$"
)
JOB_HEADER = re.compile(r"^  (?P<name>[A-Za-z_][A-Za-z0-9_-]*):[ \t]*(?:#.*)?$")


def _job_blocks(workflow: str) -> list[tuple[str, str]]:
    """Return ordinary GitHub Actions job blocks from one workflow document."""
    lines = workflow.splitlines(keepends=True)
    try:
        jobs_line = next(
            index
            for index, line in enumerate(lines)
            if re.fullmatch(r"jobs:[ \t]*(?:#.*)?\n?", line)
        )
    except StopIteration:
        return []

    jobs = lines[jobs_line + 1 :]
    starts = [index for index, line in enumerate(jobs) if JOB_HEADER.fullmatch(line.rstrip("\n"))]
    blocks: list[tuple[str, str]] = []
    for position, start in enumerate(starts):
        end = starts[position + 1] if position + 1 < len(starts) else len(jobs)
        name = JOB_HEADER.fullmatch(jobs[start].rstrip("\n")).group("name")  # type: ignore[union-attr]
        blocks.append((name, "".join(jobs[start:end])))
    return blocks


def test_python_test_jobs_use_immutable_versioned_action_revisions() -> None:
    workflows = [
        path
        for suffix in ("*.yml", "*.yaml")
        for path in WORKFLOW_DIRECTORY.glob(suffix)
        if path.is_file()
    ]
    test_jobs = [
        (path, name, body)
        for path in workflows
        for name, body in _job_blocks(path.read_text(encoding="utf-8"))
        if name.lower() in {"test", "tests"} or re.search(r"\bpytest\b", body)
    ]

    assert test_jobs, "No GitHub Actions job that runs the Python test suite was found."

    for _, name, body in test_jobs:
        uses_by_action = {
            action: [match for match in ACTION_USE.finditer(body) if match.group("action") == action]
            for action in ("actions/checkout", "actions/setup-python")
        }
        for action, uses in uses_by_action.items():
            assert uses, f"Test job {name!r} does not resolve {action}."
            for use in uses:
                assert re.fullmatch(r"[0-9a-fA-F]{40}", use.group("reference")), (
                    f"Test job {name!r} resolves {action} through mutable reference "
                    f"{use.group('reference')!r}."
                )
                assert re.fullmatch(r"[ \t]*#[ \t]*v\d+\.\d+\.\d+[ \t]*", use.group("tail")), (
                    f"Test job {name!r} must identify the release version beside its "
                    f"immutable {action} reference."
                )
